import math

def check_powers(p, a, b):
    """
    Checks if a^p-1 + b and b^p-1 + a are powers of p.
    Returns (is_valid, p_x, p_y) or (False, None, None).
    """
    try:
        # Calculate the two required values
        val1 = a**(p - 1) + b
        val2 = b**(p - 1) + a

        # Check if they are powers of p
        def is_power_of_p(n, p):
            if n <= 0:
                return False
            if n == 1: # 1 is p^0, but the problem implies positive integer powers or at least p^1 since p>2 and a,b>=1. We'll assume x, y >= 1 based on context of similar problems, but formally p^0=1. Let's check if it's exactly 1.
                # If p^x = 1, then x=0. Since a,b >= 1, a^(p-1) >= 1, b >= 1, so val1 >= 2.
                # Thus, x and y must be >= 1.
                return False

            # Check if log base p is an integer
            log_p = math.log(n) / math.log(p)
            return abs(log_p - round(log_p)) < 1e-9

        if is_power_of_p(val1, p) and is_power_of_p(val2, p):
            # Calculate the exponents x and y
            x = round(math.log(val1) / math.log(p))
            y = round(math.log(val2) / math.log(p))
            return (True, x, y)
        else:
            return (False, None, None)
    except OverflowError:
        # Handle potential overflow for larger numbers, though unlikely for a<=b<=5
        return (False, None, None)

# --- Test p = 3 ---
p3_solutions = []
P = 3
LIMIT = 5
print(f"--- Testing p = {P} (a^2 + b = 3^x, b^2 + a = 3^y) ---")

for a in range(1, LIMIT + 1):
    for b in range(a, LIMIT + 1):
        is_valid, x, y = check_powers(P, a, b)
        if is_valid:
            p3_solutions.append(((P, a, b), (x, y)))
            print(f"Found solution for p={P}, a={a}, b={b}. Powers: x={x}, y={y}")

# --- Test p = 5 ---
p5_solutions = []
P = 5
LIMIT = 5
print(f"\n--- Testing p = {P} (a^4 + b = 5^x, b^4 + a = 5^y) ---")

for a in range(1, LIMIT + 1):
    for b in range(a, LIMIT + 1):
        is_valid, x, y = check_powers(P, a, b)
        if is_valid:
            p5_solutions.append(((P, a, b), (x, y)))
            print(f"Found solution for p={P}, a={a}, b={b}. Powers: x={x}, y={y}")

print("\nSummary of p=3 solutions:")
for sol in p3_solutions:
    print(sol)

print("\nSummary of p=5 solutions:")
for sol in p5_solutions:
    print(sol)

